parts.text:
{
  "where_we_lag": {
    "headline": {
      "text": "Pohjois-Pohjanmaa lags nationally in its crude curative treatment share of 23.6% (95% CI 21.1–26.3; n=248/1050) versus 27.0% (4009/14873) across Finland.",
      "claim_ids": [
        "cty:curative:Pohjois_Pohjanmaan_hyvinvointialue",
        "nat:curative"
      ]
    },
    "details": [
      {
        "text": "The county's crude curative treatment share is 23.6% (95% CI 21.1–26.3; n=248/1050), and its 95% confidence interval excludes the national value of 27.0% (4009/14873).",
        "claim_ids": [
          "cty:curative:Pohjois_Pohjanmaan_hyvinvointialue",
          "nat:curative"
        ]
      },
      {
        "text": "Because treatment categories overlap and a patient can receive several types, the county's crude life-prolonging share is 37.4% (95% CI 34.5–40.4; n=393/1050), whose 95% confidence interval excludes the national 30.4% (4522/14873), while crude symptomatic treatment is 38.8% (95% CI 35.9–41.7; n=407/1050), whose 95% confidence interval includes the national 39.5% (5871/14873).",
        "claim_ids": [
          "cty:life_prolonging:Pohjois_Pohjanmaan_hyvinvointialue",
          "nat:life_prolonging",
          "cty:symptomatic:Pohjois_Pohjanmaan_hyvinvointialue",
          "nat:symptomatic"
        ]
      },
      {
        "text": "Furthermore, 25.0% (95% CI 22.5–27.8; n=263/1050) of patients have a crude share of no treatment record within 12 months, whose 95% confidence interval includes the national value of 27.5% (4089/14873) and is not distinguishable from it; this category mixes untreated patients and unrecorded treatment.",
        "claim_ids": [
          "cty:no_treatment_record:Pohjois_Pohjanmaan_hyvinvointialue",
          "nat:no_treatment_record",
          "bs:coverage:Treatment_start"
        ]
      },
      {
        "text": "A multidisciplinary team (MDT) meeting is recorded for a crude share of 1.1% (95% CI 0.7–2.0; n=12/1050) of county patients, whose 95% confidence interval excludes the national value of 6.0% (893/14873), although HILMO MDT codes capture only direct patient contacts and measure recording practice rather than care.",
        "claim_ids": [
          "cty:mdt_recorded:Pohjois_Pohjanmaan_hyvinvointialue",
          "nat:mdt_recorded",
          "bs:coverage:MDT",
          "q:39e6ba43a9"
        ]
      }
    ]
  },
  "how_sure_are_we": {
    "headline": {
      "text": "HILMO diagnosis concordance is about 90% in a 2019 journal article, but public report data lack age and stage adjustments (about 48% missing stage) and pathway wait timestamps.",
      "claim_ids": [
        "lit:hilmo_90",
        "bs:coverage:Diagnosis",
        "q:7885b0974f",
        "bs:coverage:Referral",
        "bs:coverage:Treatment_start"
      ]
    },
    "details": [
      {
        "text": "County shares are crude and not age-adjusted; age-adjusted values exist only in Kuva 16 for curative treatment by sex, with dashed national lines digitised from the figure (±0.5 percentage points) at 26.7% for men and 26.9% for women, and no county Kuva 16 value to test if the crude 23.6% (95% CI 21.1–26.3; n=248/1050) vs 27.0% (4009/14873) gap holds.",
        "claim_ids": [
          "cty:curative:Pohjois_Pohjanmaan_hyvinvointialue",
          "nat:curative",
          "k16:curative:men:national",
          "k16:curative:women:national"
        ]
      },
      {
        "text": "As a separate limitation, crude county treatment shares cannot be stage-adjusted because stage at diagnosis is missing for about 48% of new patients, and while a 2019 Lääkärilehti journal article found HILMO diagnoses matched the Cancer Registry for about 90% of most cancer types, that finding covers diagnosis concordance only.",
        "claim_ids": [
          "bs:coverage:Diagnosis",
          "q:7885b0974f",
          "lit:hilmo_90"
        ]
      },
      {
        "text": "Public report data do not measure symptom onset, referral dates, imaging waits (recording imaging only indirectly as the diagnosis basis in about 20% of patients), or when specialist visits or treatments occur, while primary care visits are not included in the report's data and occupational health is not mentioned.",
        "claim_ids": [
          "bs:coverage:Symptoms",
          "bs:coverage:Primary_care_occupational_health",
          "q:323de0d90d",
          "bs:coverage:Imaging",
          "q:5eb155decc",
          "bs:coverage:Referral",
          "bs:coverage:First_specialist_visit",
          "bs:coverage:Treatment_start"
        ]
      },
      {
        "text": "Preliminary, unpublished national figures from a 2025 Yle MOT study report an average of 155 days from initial symptoms to treatment in Finland versus 107 days in Sweden and 67 days in Denmark—comprising 56 days of patient delay, 41 days in primary care, and 58 days in specialist care—but no county-specific wait data exist.",
        "claim_ids": [
          "mot:total_fi",
          "mot:total_se",
          "mot:total_dk",
          "mot:patient",
          "mot:primary",
          "mot:specialist"
        ]
      }
    ]
  },
  "what_to_do_first": {
    "headline": {
      "text": "The team recommends tracking THL 21/2016 access times with handover alerts, standardising primary-care referrals and diagnostic contacts, and publishing county stage, drug and MDT recording quality.",
      "claim_ids": [
        "rec:1",
        "rec:2",
        "rec:3",
        "thl:21_2016",
        "q:556431a0c2",
        "q:82d365cd2c"
      ]
    },
    "details": [
      {
        "text": "Because Health Care Act §52 sets no legal maximum time for a cancer suspicion and the Filha programme's diagnostics recommendation with recommended time limits is to be carried out before the 2030 mid-term evaluation, the team recommends reporting referral, specialist visit, diagnosis and treatment start access times using THL guidance Ohjaus 21/2016 (16 cancers) and flagging stalled handovers.",
        "claim_ids": [
          "rec:1",
          "law:no_max",
          "thl:21_2016",
          "q:432c0e51d6",
          "q:614febebf2"
        ]
      },
      {
        "text": "Given mentor insight that a weak referral gets a lower urgency rating and while STM roadmap measure 1.2.3 plans named care-coordinator guidance by 2026–2028 (adopted by counties by 2029–2031) without specifying the care phase, the team recommends adopting a standard referral template and persistent-symptoms rule after a clear X-ray, modelled on KYS's regional pathway document, plus a named diagnostic-phase contact.",
        "claim_ids": [
          "rec:2",
          "mentor:kaisa_referral",
          "q:050ee09ebe",
          "q:abcbb06ae3",
          "reg:kys_template",
          "reg:kys_persistent"
        ]
      },
      {
        "text": "Because Pohjois-Pohjanmaa's crude recorded MDT share is 1.1% (95% CI 0.7–2.0; n=12/1050) versus 6.0% (893/14873) nationally—measuring recording practice, not care—and stage is missing for about 48% of patients while national data reporting is incomplete, the team recommends publishing per-county stage, drug treatment and MDT coding and reading county gaps in these fields as data-quality signals.",
        "claim_ids": [
          "rec:3",
          "cty:mdt_recorded:Pohjois_Pohjanmaan_hyvinvointialue",
          "nat:mdt_recorded",
          "bs:coverage:MDT",
          "bs:coverage:Diagnosis",
          "q:7885b0974f",
          "q:950a2f797b",
          "q:82d365cd2c"
        ]
      }
    ]
  }
}
